:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #e0e0e0;
  --accent: #ffcc00;
  --accent-hover: #ffdb4d;
  --accent-pressed: #e6b800;
  --border: #44445a;
  --btn-bg: #3a3a55;
  --btn-hover: #4a4a6a;
  --btn-pressed: #2a2a40;
  --focus: #ffcc00;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 2px solid var(--border);
  border-radius: 12px;
  padding: 24px;
  max-width: 400px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  margin-bottom: 20px;
  color: var(--accent);
  letter-spacing: 1px;
}

.display {
  display: flex;
  justify-content: space-between;
  background: #111122;
  border: 2px solid var(--border);
  border-radius: 8px;
  padding: 12px 16px;
  margin-bottom: 24px;
  gap: 8px;
}

.floor-display,
.direction-display,
.door-display {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1;
}

.label {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #8888aa;
  margin-bottom: 4px;
}

.value {
  font-size: 1.25rem;
  font-weight: bold;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.panel {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}

.floor-btn {
  font-family: inherit;
  font-size: 1.25rem;
  font-weight: bold;
  padding: 16px 0;
  background: var(--btn-bg);
  color: var(--text);
  border: 2px solid var(--border);
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.floor-btn:hover {
  background: var(--btn-hover);
  border-color: var(--accent);
}

.floor-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.floor-btn:active,
.floor-btn[aria-pressed="true"] {
  background: var(--accent-pressed);
  border-color: var(--accent);
  color: #111122;
  transform: scale(0.97);
}

.hint {
  margin-top: 20px;
  font-size: 0.875rem;
  text-align: center;
  color: #8888aa;
  line-height: 1.4;
}

[hidden] {
  display: none !important;
}

@media (max-width: 360px) {
  .card {
    padding: 16px;
  }
  .display {
    flex-direction: column;
    gap: 8px;
  }
  .floor-display,
  .direction-display,
  .door-display {
    flex-direction: row;
    justify-content: space-between;
  }
  .label {
    margin-bottom: 0;
  }
  .floor-btn {
    font-size: 1.1rem;
    padding: 12px 0;
  }
}

(function () {
  'use strict';

  const MIN_FLOOR = 1;
  const MAX_FLOOR = 6;
  const MOVE_MS = 1000;
  const DOOR_OPEN_MS = 1500;

  const state = {
    currentFloor: 1,
    direction: 'idle',
    doorsOpen: false,
    queue: [],
    moving: false,
    doorTimer: null,
  };

  const els = {
    currentFloor: document.getElementById('current-floor'),
    direction: document.getElementById('direction'),
    doorStatus: document.getElementById('door-status'),
    buttons: Array.from(document.querySelectorAll('.floor-btn')),
  };

  function render() {
    els.currentFloor.textContent = String(state.currentFloor);
    els.direction.textContent =
      state.direction === 'up' ? 'Up' :
      state.direction === 'down' ? 'Down' : 'Idle';
    els.doorStatus.textContent = state.doorsOpen ? 'Open' : 'Closed';

    els.buttons.forEach(function (btn) {
      const floor = Number(btn.dataset.floor);
      const queued = state.queue.indexOf(floor) !== -1;
      btn.setAttribute('aria-pressed', queued ? 'true' : 'false');
    });
  }

  function enqueue(floor) {
    if (floor < MIN_FLOOR || floor > MAX_FLOOR) return;
    if (state.queue.indexOf(floor) !== -1) return;
    if (floor === state.currentFloor && !state.moving) return;
    state.queue.push(floor);
    render();
    if (!state.moving && !state.doorsOpen) {
      step();
    }
  }

  function pickNextTarget() {
    if (state.queue.length === 0) return null;
    let best = null;
    let bestDist = Infinity;
    for (let i = 0; i < state.queue.length; i++) {
      const f = state.queue[i];
      const dist = Math.abs(f - state.currentFloor);
      if (dist < bestDist) {
        bestDist = dist;
        best = f;
      }
    }
    return best;
  }

  function step() {
    if (state.moving || state.doorsOpen) return;
    const target = pickNextTarget();
    if (target === null) {
      state.direction = 'idle';
      render();
      return;
    }

    if (target === state.currentFloor) {
      openDoors(target);
      return;
    }

    state.moving = true;
    state.direction = target > state.currentFloor ? 'up' : 'down';
    render();

    setTimeout(function () {
      state.currentFloor += state.direction === 'up' ? 1 : -1;
      state.moving = false;
      render();

      if (state.currentFloor === target) {
        openDoors(target);
      } else {
        step();
      }
    }, MOVE_MS);
  }

  function openDoors(floor) {
    state.doorsOpen = true;
    state.direction = 'idle';
    render();

    state.doorTimer = setTimeout(function () {
      state.doorsOpen = false;
      const idx = state.queue.indexOf(floor);
      if (idx !== -1) state.queue.splice(idx, 1);
      render();
      step();
    }, DOOR_OPEN_MS);
  }

  els.buttons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      enqueue(Number(btn.dataset.floor));
    });
  });

  render();
})();
